<script lang="ts">
import {editIcon} from '@awc-ui/showcase-kit/design';
import {document} from '$lib/document'; import {t} from '$lib/showcase'; import {navigate} from '$lib/router'; import Link from '$lib/components/Link.svelte';
$: entries = $document.history.entries; $: index = $document.history.index;
</script>
<div class="history studio-history" data-history><div class="studio-panel-head"><strong>{$t('Time machine')}</strong><span>{entries.length} {$t('edits')}</span></div><p class="studio-tip">{$t('Revisit any step. Making a new edit replaces the redo branch.')}</p><button class="history__row" data-current={index === 0 ? '' : undefined} on:click={() => $document.jumpHistory(0)}><span class="material-symbols-outlined" aria-hidden="true">flag</span><span><strong>{$t('Starting canvas')}</strong><small>{$t('Your document before these edits')}</small></span>{#if index === 0}<span class="studio-history__current">{$t('Current')}</span>{/if}</button>{#each entries as entry, i}<button class="history__row" data-edit={entry.kind} data-undone={i >= index ? '' : undefined} data-current={i === index - 1 ? '' : undefined} on:click={() => $document.jumpHistory(i + 1)}><span class="material-symbols-outlined" aria-hidden="true">{editIcon(entry.kind)}</span><span><strong>{$t(entry.labelKey)}</strong><small>{entry.after[0]?.name ?? entry.before[0]?.name ?? $t('Canvas')}{#if Math.max(entry.before.length, entry.after.length) > 1}{$t(' + {count} more', {count: Math.max(entry.before.length, entry.after.length) - 1})}{:else}{''}{/if}</small></span>{#if i === index - 1}<span class="studio-history__current">{$t('Current')}</span>{:else}<span class="studio-history__number">{i + 1}</span>{/if}</button>{/each}{#if entries.length === 0}<div class="studio-history-empty"><span class="material-symbols-outlined" aria-hidden="true">history</span><p>{$t('Your next idea starts here. Every change is reversible.')}</p></div>{/if}</div>
